  /* ---------- YENİ (v64): MUTABAKAT TARİHİ HEDEF KONUMU MANUEL YERLEŞTİRME ----------
     Yalnızca otomatik HEDEF yer tutucu tespiti (anchors.reconciliationDateTarget) başarısız
     olduğunda ve kullanıcı henüz manuel bir hedef konum belirlemediğinde (rec.manualReconciliationDateTarget)
     önizleme canvas'ı tıklanabilir hale gelir: "Tarihi itibariyle" ifadesinin önündeki alana tıklanır,
     küçük bir tarih giriş kutusu açılır, girilen değer normalize edilip HEM formdaki "Mutabakat
     Tarihi" alanına (rec.manualReconciliationDate) HEM de konuma (rec.manualReconciliationDateTarget)
     yazılır — SADECE o kayıt için saklanır (rec bazlı state, diğer kayıtları asla etkilemez). Zaten
     bir manuel konum varsa, yatay olarak sürüklenebilen küçük bir rozet gösterilir. Öncelik HER ZAMAN
     otomatik tespittedir — bu yalnızca otomatik tespit gerçekten başarısız olduğunda devreye girer. */
  function cmRenderMutabakatDateOverlay(rec, canvas, wrap){
    wrap.querySelectorAll('.cm-date-hint,.cm-date-pill,.cm-date-inline-input').forEach(el=>el.remove());
    const a = rec.anchors;
    const autoTargetFound = !!(a && a.reconciliationDateTarget);
    const needsManualTarget = !autoTargetFound && !rec.manualReconciliationDateTarget;

    // CSS piksel <-> PDF nokta dönüşüm oranı: canvas'ın EKRANDA gösterilen genişliği / PDF sayfa genişliği.
    function scaleFactor(){
      const cssW = canvas.clientWidth || canvas.width;
      return cssW / (rec.pageWidth || 595);
    }
    function pdfToCanvasPx(xPdf, yTop){
      const s = scaleFactor();
      return { left: canvas.offsetLeft + xPdf*s, top: canvas.offsetTop + yTop*s };
    }
    function canvasPxToPdf(cssX, cssY){
      const s = scaleFactor();
      return { xPdf: cssX / s, yTop: cssY / s };
    }
    // Manuel tıklama noktasına en yakın "tarihi itibariyle" satırının GERÇEK punto yüksekliğini
    // bulur (bulunamazsa 10pt makul varsayılana düşer) — manuel yerleştirilen tarih de PDF'nin
    // gerçek yazı boyutuna yakın görünsün diye.
    function estimateFontSizeNear(yTop){
      if(!rec.items || !rec.items.length) return 10;
      try{
        const lines = cmGroupItemsIntoLines(rec.items, 3);
        const phraseRe = /TARIHI\s*ITIBARIYLE/;
        let best = null, bestDist = Infinity;
        lines.forEach(line=>{
          if(phraseRe.test(cmComparable(line.text))){
            const dist = Math.abs(line.yMin - yTop);
            if(dist < bestDist){ bestDist = dist; best = line; }
          }
        });
        if(best) return Math.max(8, (best.yMax - best.yMin) / 1.05);
      }catch(e){}
      return 10;
    }

    function currentPillText(){
      if(rec.manualReconciliationDate && rec.manualReconciliationDate.trim()) return rec.manualReconciliationDate.trim();
      if(a && a.sourceReconciliationDate) return cmNormalizeReconciliationDateText(a.sourceReconciliationDate.text);
      return '(tarih girilmedi)';
    }

    function commitManualTarget(rawInput, xPdf, yTop, fontSize){
      const formatted = cmNormalizeReconciliationInput(rawInput);
      if(formatted) rec.manualReconciliationDate = formatted;
      rec.manualReconciliationDateTarget = { xPdf, yTop, fontSize: fontSize || estimateFontSizeNear(yTop) };
      cmRenderForm(); // "Mutabakat Tarihi" alanının görünürlüğünü/değerini de tazeler
      cmSchedulePreview();
    }

    function openInlineInput(cssLeft, cssTop, prefill, xPdf, yTop){
      wrap.querySelectorAll('.cm-date-inline-input').forEach(el=>el.remove());
      const input = document.createElement('input');
      input.type = 'text';
      input.className = 'cm-date-inline-input';
      input.style.left = cssLeft + 'px';
      input.style.top = cssTop + 'px';
      input.value = prefill || '';
      input.placeholder = 'ör. 30/06/'+new Date().getFullYear();
      wrap.appendChild(input);
      input.focus();
      input.select();
      let committed = false;
      function finish(){
        if(committed) return;
        committed = true;
        if(input.value.trim()){ commitManualTarget(input.value, xPdf, yTop); }
        input.remove();
      }
      input.addEventListener('keydown', (e)=>{
        if(e.key === 'Enter'){ finish(); }
        else if(e.key === 'Escape'){ committed = true; input.remove(); }
      });
      input.addEventListener('blur', finish);
    }

    if(rec.manualReconciliationDateTarget){
      const mt = rec.manualReconciliationDateTarget;
      const pos = pdfToCanvasPx(mt.xPdf, mt.yTop);
      const pill = document.createElement('div');
      pill.className = 'cm-date-pill';
      pill.style.left = pos.left + 'px';
      pill.style.top = (pos.top - 9) + 'px';
      pill.innerHTML = '<span class="cm-date-pill-text"></span><span class="cm-date-pill-x" title="Kaldır">✕</span>';
      pill.querySelector('.cm-date-pill-text').textContent = currentPillText();
      wrap.appendChild(pill);

      pill.querySelector('.cm-date-pill-x').addEventListener('click', (e)=>{
        e.stopPropagation();
        rec.manualReconciliationDateTarget = null;
        cmRenderStatusBox(rec);
        cmSchedulePreview();
      });

      let dragging = false, moved = false, dragStartX = 0, pillStartLeft = 0;
      pill.addEventListener('mousedown', (e)=>{
        if(e.target.closest('.cm-date-pill-x')) return;
        e.preventDefault();
        dragging = true; moved = false;
        dragStartX = e.clientX;
        pillStartLeft = pill.offsetLeft;
        pill.classList.add('cm-dragging');
        const onMove = (ev)=>{
          if(!dragging) return;
          const dx = ev.clientX - dragStartX;
          if(Math.abs(dx) > 2) moved = true;
          let newLeft = pillStartLeft + dx;
          newLeft = Math.max(canvas.offsetLeft, Math.min(canvas.offsetLeft + canvas.clientWidth - 20, newLeft));
          pill.style.left = newLeft + 'px';
        };
        const onUp = ()=>{
          dragging = false;
          pill.classList.remove('cm-dragging');
          document.removeEventListener('mousemove', onMove);
          document.removeEventListener('mouseup', onUp);
          if(moved){
            const cssLeft = pill.offsetLeft - canvas.offsetLeft;
            const p = canvasPxToPdf(cssLeft, mt.yTop * scaleFactor());
            rec.manualReconciliationDateTarget = Object.assign({}, mt, { xPdf: p.xPdf });
            cmSchedulePreview();
          } else {
            openInlineInput(pill.offsetLeft, pill.offsetTop, currentPillText(), mt.xPdf, mt.yTop);
          }
        };
        document.addEventListener('mousemove', onMove);
        document.addEventListener('mouseup', onUp);
      });
      return;
    }

    if(needsManualTarget){
      canvas.classList.add('cm-date-clickable');
      const hint = document.createElement('div');
      hint.className = 'cm-date-hint';
      hint.textContent = 'Mutabakat tarihi hedef konumu otomatik bulunamadı — "Tarihi itibariyle" ifadesinin önündeki alana tıklayın.';
      wrap.appendChild(hint);

      canvas.addEventListener('click', function onCanvasClick(e){
        const rect = canvas.getBoundingClientRect();
        const cssX = e.clientX - rect.left;
        const cssY = e.clientY - rect.top;
        const p = canvasPxToPdf(cssX, cssY);
        const prefill = rec.manualReconciliationDate || ((a && a.sourceReconciliationDate) ? a.sourceReconciliationDate.text : '');
        openInlineInput(canvas.offsetLeft + cssX, canvas.offsetTop + cssY - 12, prefill, p.xPdf, p.yTop);
      }, { once: true });
    }
  }

  async function cmRenderPreview(){ return cm91Render(); }

  /* ---------- TEKLİ İNDİRME ---------- */
  document.getElementById('cmDownloadOne').addEventListener('click', async ()=>{
    const rec = cmRecords.find(r=>r.id===cmSelectedId);
    if(!rec){ cmToast('Önce bir mutabakat seç.'); return; }
    const missing = cmEvaluateReady(rec);
    if(missing.length){ cmToast('Bu mutabakat henüz hazır değil: ' + missing[0]); return; }
    try{
      // Her indirmede taze PDF üret (form değişikliği ile indirme arasında eski veri riskini önler)
      const bytes = await cmBuildPdf(rec);
      // YENİ: cmBuildPdf az önce rec.overlayFitBlocked'ı TAZE olarak hesapladı (ör. tutar dinamik
      // puntoda bile alana sığmadıysa) — indirme burada, dosya kaydedilmeden HEMEN ÖNCE tekrar
      // kontrol edilerek kesin olarak engellenir (yalnızca üstteki ön-kontrole güvenilmez).
      if(rec.overlayFitBlocked){
        cmRenderStatusBox(rec);
        cmToast('İndirme engellendi: ' + ((rec.buildIssues && rec.buildIssues.length) ? rec.buildIssues.join(' ') : 'Tutar alana sığmıyor.'));
        return;
      }
      const existingNames = new Set();
      const blob = new Blob([bytes], {type:'application/pdf'});
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = cmBuildFileName(rec.company, rec.counterparty, existingNames);
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(()=>URL.revokeObjectURL(url), 1500);
      cmToast('Mutabakat indirildi.');
    }catch(err){
      cmToast('İndirme başarısız: ' + (err && err.message ? err.message : err));
    }
  });
  /* ---------- HAZIR OLANLARIN TÜMÜNÜ İNDİR ---------- */
  document.getElementById('cmDownloadReady').addEventListener('click', async ()=>{
    const btn = document.getElementById('cmDownloadReady');
    const readyRecords = cmRecords.filter(r => cmEvaluateReady(r).length === 0 && !r.skip);
    if(!readyRecords.length){ cmToast('Hazır durumda dosya yok.'); return; }

    btn.disabled = true;
    const originalText = btn.textContent;
    btn.textContent = 'Hazırlanıyor…';
    const existingNames = new Set();
    try{
      if(readyRecords.length === 1){
        const rec = readyRecords[0];
        // Her indirmede taze PDF üret (form değişikliği ile indirme arasında eski veri riskini önler)
        const bytes = await cmBuildPdf(rec);
        // YENİ: tazelenmiş overlayFitBlocked bayrağı, dosya kaydedilmeden hemen önce son kez kontrol edilir.
        if(rec.overlayFitBlocked){
          cmRenderStatusBox(rec);
          cmToast('İndirme engellendi: ' + ((rec.buildIssues && rec.buildIssues.length) ? rec.buildIssues.join(' ') : 'Tutar alana sığmıyor.'));
          return;
        }
        const blob = new Blob([bytes], {type:'application/pdf'});
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = cmBuildFileName(rec.company, rec.counterparty, existingNames);
        document.body.appendChild(a); a.click(); a.remove();
        setTimeout(()=>URL.revokeObjectURL(url), 1500);
        cmToast('1 mutabakat indirildi.');
      } else {
        if(typeof JSZip === 'undefined'){
          cmToast('Toplu indirme için gerekli kütüphane (JSZip) yüklenemedi — internet bağlantını kontrol et.');
          return;
        }
        const zip = new JSZip();
        let ok = 0, fail = 0;
        for(const rec of readyRecords){
          try{
            // Her indirmede taze PDF üret (form değişikliği ile indirme arasında eski veri riskini önler)
            const bytes = await cmBuildPdf(rec);
            // YENİ: tazelenmiş overlayFitBlocked bayrağı — sığmıyorsa bu kayıt zip'e eklenmeden atlanır.
            if(rec.overlayFitBlocked){ fail++; continue; }
            const fname = cmBuildFileName(rec.company, rec.counterparty, existingNames);
            existingNames.add(fname);
            zip.file(fname, bytes);
            ok++;
          }catch(e){ fail++; }
        }
        const zipBlob = await zip.generateAsync({type:'blob'});
        const url = URL.createObjectURL(zipBlob);
        const a = document.createElement('a');
        const today = cmTodayStr();
        a.href = url; a.download = `Cari Mutabakatlar - ${today}.zip`;
        document.body.appendChild(a); a.click(); a.remove();
        setTimeout(()=>URL.revokeObjectURL(url), 1500);
        cmToast(`${ok} dosya ZIP içinde indirildi${fail?`, ${fail} başarısız`:''}.`);
      }
    }catch(err){
      cmToast('Toplu indirme başarısız: ' + (err && err.message ? err.message : err));
    }finally{
      btn.disabled = false;
      btn.textContent = originalText;
    }
  });

  /* Cari Mutabakat: belgeye özel, PDF nokta koordinatlı düzenleyici. */
  const cm91 = {page:1, zoom:1, tool:'select', selected:null, preview:false, token:0, viewport:null};
  const cm91Current = ()=>cmRecords.find(r=>r.id===cmSelectedId);
  const cm91State = r=>r.cm91||(r.cm91={items:[],undo:[],redo:[],auto:false,dirty:false});
